__NUXT_JSONP__("/desarrollo-sostenible/columnas/2020_la_nueva_politica_energetica_que_mata_a_la_politica_climatica", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H){return {data:[{post:{slug:p,title:q,date:r,img:s,autor:t,medio:u,link:v,category:j,extracto:k,toc:[],body:{type:l,children:[{type:b,tag:c,props:{},children:[{type:b,tag:w,props:{},children:[{type:a,value:x}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:y}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:k}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:z}]}]},dir:m,path:A,extension:n,createdAt:o,updatedAt:o},columnas:[{slug:"10_temas_de_agenda_urbana_para_la_ciudad_de_mexico",title:"10 temas de agenda urbana para la Ciudad de México",date:"2013-11-29T00:50:27.798Z",img:"https:\u002F\u002Fucarecdn.com\u002Fc0fc0d3b-31f3-4bdc-83d8-9aed2e2c0c7b\u002F",autor:"José Luis Chicoma, Carey Dunfey, Marie Sorba",medio:B,category:j,extracto:C,toc:[],body:{type:l,children:[{type:b,tag:c,props:{},children:[{type:a,value:C}]}]},dir:m,path:"\u002Fcolumnas\u002F10_temas_de_agenda_urbana_para_la_ciudad_de_mexico",extension:n,createdAt:D,updatedAt:D},{slug:p,title:q,date:r,img:s,autor:t,medio:u,link:v,category:j,extracto:k,toc:[],body:{type:l,children:[{type:b,tag:c,props:{},children:[{type:b,tag:w,props:{},children:[{type:a,value:x}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:y}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:k}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:z}]}]},dir:m,path:A,extension:n,createdAt:o,updatedAt:o},{slug:"america_central_al_filo_de_la_catastrofe_climatica",title:"América Central, al filo de la catástrofe climática",date:"2022-05-04T00:22:43.446Z",img:"https:\u002F\u002Fucarecdn.com\u002Fba1863f0-0f73-4e36-b3b9-0d3ceee2b375\u002F",autor:"Ana Paula Sandoval y Verne Martínez",medio:B,link:"https:\u002F\u002Fwww.animalpolitico.com\u002Fblog-invitado\u002Famerica-central-al-filo-de-la-catastrofe-climatica\u002F",category:j,extracto:"Según datos del último reporte del Panel Intergubernamental de Cambio Climático (IPCC), más de tres mil millones de personas viven en contextos de alta vulnerabilidad al cambio climático derivado del aumento de la temperatura mundial; esto se ha reflejado en el incremento del nivel del mar, sequías y fenómenos meteorológicos extremos como tormentas, huracanes y mega incendios.",toc:[],body:{type:l,children:[{type:b,tag:c,props:{},children:[{type:a,value:"Según datos del último reporte del "},{type:b,tag:e,props:{href:E,rel:[f,g,h],target:i},children:[{type:a,value:"Panel Intergubernamental de Cambio Climático (IPCC"}]},{type:b,tag:e,props:{href:E,rel:[f,g,h],target:i},children:[{type:a,value:")"}]},{type:a,value:", más de tres mil millones de personas viven en contextos de alta vulnerabilidad al cambio climático derivado del aumento de la temperatura mundial; esto se ha reflejado en el incremento del nivel del mar, sequías y fenómenos meteorológicos extremos como tormentas, huracanes y mega incendios."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De acuerdo con estimaciones presentadas a través del "},{type:b,tag:e,props:{href:"https:\u002F\u002Fgermanwatch.org\u002Fsites\u002Fdefault\u002Ffiles\u002FResumen%20Indice%20de%20Riesgo%20Clim%C3%A1tico%20Global%202021.pdf",rel:[f,g,h],target:i},children:[{type:a,value:"Índice de Riesgo Climático Global"}]},{type:a,value:", Centroamérica es una de las regiones más susceptibles a riesgos climatológicos. Esto se ha percibido de manera clara por el aumento de la temperatura de entre 0.7 °C y 1 °C desde mediados de los años setenta y por una tendencia decreciente en las precipitaciones anuales. Las variaciones en el clima (lluvias intensas, periodos de sequías, cambios en el patrón de las lluvias, etc.) inciden directamente en la capacidad de producción de la región y del sector como tal; evidencia de ello es que, con los cambios drásticos en el clima en años recientes, se ha visto una afectación enorme en la producción de granos básicos como maíz y frijol, ingredientes indispensables en las dietas de la población, lo que genera a su vez altos niveles de hambre y malnutrición."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Además de estas amenazas ocasionadas por factores climáticos, esta región padece también vulnerabilidades a raíz de la desigualdad social, inestabilidad política, inseguridad y conflictos armados que se traducen en la tormenta perfecta para la catástrofe. Más de la mitad de la población está en situación de pobreza y la mayoría se ubica en los países del Triángulo Norte, una de las regiones más desiguales y vulnerables a la crisis climática."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La crisis derivada del cambio climático no es algo nuevo, desde la década de 1970, una organización pionera conformada por científicos, políticos y activistas conocida como el Club de Roma advertía sobre los principales efectos asociados al incremento exponencial en las emisiones de gases de efecto invernadero y el uso ineficiente y desmedido de los recursos. En concordancia con lo planteado, para inicios "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.millenniumassessment.org\u002Fdocuments\u002Fdocument.354.aspx.pdf",rel:[f,g,h],target:i},children:[{type:a,value:"del nuevo siglo"}]},{type:a,value:" se observaba que la tasa de extinción de especies eran de hasta mil veces mayor que cualquier otro momento histórico del que se tenga registro, la tasa de modificación de ecosistemas inalterados para uso humano se incrementó hasta en 50%, la diversidad genética se redujo drásticamente, y por lo tanto, se registró un incremento constante en las emisiones de carbono. Actualmente, estas estimaciones apuntan a que la contribución al fenómeno del calentamiento global ha sido generada hasta en "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.thelancet.com\u002Fjournals\u002Flanplh\u002Farticle\u002FPIIS2542-5196(20)30196-0\u002Ffulltext",rel:[f,g,h],target:i},children:[{type:a,value:"82% por países del norte global"}]},{type:a,value:", mientras que para el caso de Centroamérica este dato se reduce tan solo al "},{type:b,tag:e,props:{href:F,rel:[f,g,h],target:i},children:[{type:a,value:"0.26% de las emisiones a nivel global."}]},{type:b,tag:e,props:{href:F,rel:[f,g,h],target:i},children:[{type:a,value:" "}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Los últimos pronósticos apuntan que para poder evitar fenómenos de calentamiento catastróficos y permanecer por debajo de un calentamiento de 1.5° se necesita una "},{type:b,tag:e,props:{href:G,rel:[f,g,h],target:i},children:[{type:a,value:"r"}]},{type:b,tag:e,props:{href:G,rel:[f,g,h],target:i},children:[{type:a,value:"educción de hasta 70%"}]},{type:a,value:" en la extracción y aprovechamiento de los recursos naturales para países de altos ingresos. Existe una relación importante entre el fenómeno de desigualdad creciente a nivel global con la forma en que los efectos del cambio climático se focalizan, ya que estos suelen afectar en mayor proporción a regiones y países que han contribuido de manera marginal al fenómeno, pero donde los efectos adversos derivados de esta problemática se intensifican, poniendo en una situación de alto riesgo a los ya híper vulnerables."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En América Central, la crisis humanitaria ocasionada por el cambio climático es evidente y creciente a lo largo de toda la región, como resultado de la degradación de los sistemas agrícolas, el desplazamiento por el incremento en el nivel del mar, la presencia de eventos climáticos extremos y los efectos económicos que estos eventos implican. Algunas estimaciones apuntan a que entre 1998 y 2017 se perdieron"},{type:b,tag:e,props:{href:"https:\u002F\u002Fgermanwatch.org\u002Fsites\u002Fdefault\u002Ffiles\u002FIndice%20de%20Riesgo%20Climatico%20Global%202019%20-%20Resumen_0.pdf",rel:[f,g,h],target:i},children:[{type:a,value:" más de 520,000 vidas"}]},{type:a,value:" como consecuencia directa de eventos meteorológicos extremos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Esta crisis generada a nivel global y focalizada a nivel regional ha tenido como consecuencia una enorme cantidad de refugiados climáticos, nombre con el que se identifica a aquellas personas que debido a los efectos ocasionados por el calentamiento global, se ven obligados a  migrar, y que a la fecha son más de 50 millones en el mundo, aproximadamente. Para el caso de Centroamérica, el Banco Mundial calcula (bajo condiciones pesimistas) que para 2050 podría haber hasta "},{type:b,tag:e,props:{href:H,rel:[f,g,h],target:i},children:[{type:a,value:"3.9 millones de "}]},{type:b,tag:e,props:{href:H,rel:[f,g,h],target:i},children:[{type:a,value:"refugiados climáticos"}]},{type:a,value:". Esta cifra está alineada con los escenarios presentados por el "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.ipcc.ch\u002Freport\u002Far6\u002Fwg1\u002F#SPM",rel:[f,g,h],target:i},children:[{type:a,value:"IPCC"}]},{type:a,value:", para quien los efectos se acrecentarán en proporción al aumento de la temperatura."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Estos datos son alarmantes. Es urgente la acción y cooperación internacional para reducir los efectos del cambio climático a través de políticas de mitigación a nivel global en las cuales los países que contribuyen principalmente a esta problemática se responsabilicen y tomen acciones claras y concretas para revertirla."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"También debe ser prioridad respaldar definiciones como la de refugiado climático en el marco jurídico internacional con el objetivo de ofrecer alternativas y soporte a grupos cuya única alternativa para sobrevivir es la migración."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Es apremiante potenciar y expandir la aplicación de medidas dirigidas hacia la mitigación y adaptación al cambio climático en las zonas de mayor vulnerabilidad, como América Central. En este sentido, el fortalecimiento institucional es esencial para la aplicación de estrategias dirigidas a la mitigación de los efectos existentes; se necesitan esquemas de gobernanza fortalecidos, planificación hacia la mejora en la infraestructura, gestión integrada hacia el manejo eficiente de recursos naturales y la provisión de servicios que garanticen una vida digna. Es momento de que los países del norte asuman su responsabilidad y potencien acciones que, por un lado, reduzcan las emisiones que contribuyen al cambio climático y, por otro, ayuden a reducir los impactos de esta crisis climática en los países del sur global, que sin deberla son quienes se ven más afectados."}]}]},dir:m,path:"\u002Fcolumnas\u002Famerica_central_al_filo_de_la_catastrofe_climatica",extension:n,createdAt:"2023-06-19T05:11:57.378Z",updatedAt:"2022-08-30T00:39:54.037Z"}]}],fetch:{},mutations:[]}}("text","element","p","\n","a","nofollow","noopener","noreferrer","_blank","desarrollo-sostenible","Destinar 86,000 millones de pesos a fortalecer la producción petrolera del país resta recursos para impulsar la transición energética, y en este contexto urge comenzar a activar una política energética alineada a una estrategia que entienda la emergencia climática. La nueva política energética es muy clara.","root","\u002Fcolumnas",".md","2023-09-12T15:29:17.027Z","2020_la_nueva_politica_energetica_que_mata_a_la_politica_climatica","2020: La nueva política energética que mata a la política climática","2019-09-14T23:15:47.844Z","https:\u002F\u002Fucarecdn.com\u002F81255dcf-e10e-435b-bf72-77aca4d9d53d\u002F","Aleithya Morales","Expansion ","https:\u002F\u002Fexpansion.mx\u002Fopinion\u002F2019\u002F09\u002F14\u002F2020-la-nueva-politica-energetica-que-mata-a-la-politica-climatica","em","Destinar 86,000 millones de pesos a fortalecer la producción petrolera del país resta recursos para impulsar la transición energética, dice Aleithya Morales.","En estos recientes días el Primer Informe de Gobierno y la presentación de la propuesta del Paquete Económico 2020 reafirman las prioridades del gobierno al opacar la política climática.","En el Anexo 16 del Paquete Económico, donde se presentan los Recursos para la Adaptación y Mitigación de los Efectos del Cambio Climático, a pesar de que se propone un aumento de 42% en este rubro, el mayor beneficiado es la Comisión Federal de Electricidad (CFE) con el 73% de los recursos incluyendo el Servicio de transporte de gas natural.","\u002Fcolumnas\u002F2020_la_nueva_politica_energetica_que_mata_a_la_politica_climatica","Animal Politico","10 temas relevantes para la agenda de desarrollo urbano, que pueden convertir a las ciudades en centros de oportunidades e integración para su gente.","2023-09-12T15:29:17.026Z","https:\u002F\u002Fwww.ipcc.ch\u002Freport\u002Far6\u002Fwg1\u002F","https:\u002F\u002Fwww.cepal.org\u002Fes\u002Fpublicaciones\u002F45677-la-emergencia-cambio-climatico-america-latina-caribe-seguimos-esperando-la","https:\u002F\u002Fwww.theguardian.com\u002Fenvironment\u002F2022\u002Fapr\u002F06\u002Fus-europe-behind-vast-majority-global-ecological-damage-study","https:\u002F\u002Fwww.bbc.com\u002Fmundo\u002Fnoticias-america-latina-49696180")));